    defer _gui_active_backend.deinitFn();
    const _g = GuiContext{ ._b = &_gui_active_backend, .lowLevel = .{ ._b = &_gui_active_backend } };
    if (comptime @typeInfo(@TypeOf(frame)) == .@"fn") {
